<section class="section"><div class="container"><h2 class="font-weight-bold mb-2">ประกาศของฉัน</h2><p class="text-muted">จัดการสถานะหรือลบประกาศที่คุณสร้างไว้</p><?php if(session('success')): ?><div class="alert alert-success"><?php echo e(session('success')); ?></div><?php endif; ?>
